import{_ as l,a0 as o,w as p,s as u,I as e,x as a,a1 as n,A as s,ao as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"GitHub 是如何遷移 MySQL 集羣的 | LCTT x X-CMD","titleTemplate":false,"description":"GitHub 是如何遷移 MySQL 集羣的 | LCTT (201410) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"GitHub 是如何遷移 MySQL 集羣的 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"GitHub 是如何遷移 MySQL 集羣的 | LCTT (201410) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201410/20140904 Making MySQL Better at GitHub","title":"GitHub 是如何遷移 MySQL 集羣的","tag":"201410","desc":""},"relativePath":"201410/20140904 Making MySQL Better at GitHub.md","filePath":"[post].md"}'),d={name:"201410/20140904 Making MySQL Better at GitHub.md"};function b(m,t,g,f,h,T){const i=o("Link");return p(),u("div",null,[t[23]||(t[23]=e("h1",{id:"github-是如何遷移-mysql-集羣的",tabindex:"-1"},[a("GitHub 是如何遷移 MySQL 集羣的 "),e("a",{class:"header-anchor",href:"#github-是如何遷移-mysql-集羣的","aria-label":"Permalink to “GitHub 是如何遷移 MySQL 集羣的”"},"​")],-1)),e("blockquote",null,[e("p",null,[t[1]||(t[1]=a("在 GitHub 我們總是説“如果網站響應速度不夠快，我們就不應該讓它上線運營”。我們之前在",-1)),n(i,{href:"https://github.com/blog/1756-optimizing-large-selector-sets"},{default:s(()=>[...t[0]||(t[0]=[a("前端的體驗速度",-1)])]),_:1}),t[2]||(t[2]=a("這篇文章中介紹了一些提高網站響應速率的方法，但這只是故事的一部分。真正影響到 GitHub.com 性能的因素是 MySQL 資料庫架構。讓我們來瞧瞧我們的基礎架構團隊是如何無縫升級了 MySQL 架構吧，這事兒發生在去年8月份，成果就是大大提高了 GitHub 網站的速度。",-1))])]),t[24]||(t[24]=r('<h3 id="任務" tabindex="-1">任務 <a class="header-anchor" href="#任務" aria-label="Permalink to “任務”">​</a></h3><p>去年我們把 GitHub 上的大部分數據移到了新的數據中心，這個中心有世界頂級的硬件資源和網絡平台。自從使用了 MySQL 作為我們的後端系統的基礎，我們一直期望着一些改進來大大提高資料庫性能，但是在數據中心使用全新的硬件來部署一套全新的集羣環境並不是一件簡單的工作，所以我們制定了一套計劃和測試工作，以便數據能平滑過渡到新環境。</p><h3 id="準備工作" tabindex="-1">準備工作 <a class="header-anchor" href="#準備工作" aria-label="Permalink to “準備工作”">​</a></h3><p>像我們這種關於架構上的巨大改變，在執行的每一步都需要收集數據指標。新機器上安裝好了基本的操作系統，接下來就是測試新配置下的各種性能。為了模擬真實的工作負載環境，我們使用 tcpdump 工具從舊的集羣那裏複製正在發生的 SELECT 請求，並在新集羣上重新回放一遍。</p><p>MySQL 調優是個繁瑣的細緻活，像眾所周知的 innodb_buffer_pool_size 這個參數往往能對 MySQL 性能產生巨大的影響。對於這類參數，我們必須考慮在內，所以我們列了一份參數清單，包括 innodb_thread_concurrency，innodb_io_capacity，和 innodb_buffer_pool_instances，還有其它的。</p><p>在每次測試中，我們都很小心地只改變一個參數，並且讓一次測試至少運行12小時。我們會觀察響應時間的變化曲線，每秒的響應次數，以及有可能會導致併發性降低的參數。我們使用 “SHOW ENGINE INNODB STATUS” 命令打印 InnoDB 性能信息，特別觀察了 “SEMAPHORES” 一節的內容，它為我們提供了工作負載的狀態信息。</p><p>當我們在設置參數後對運行結果感到滿意，然後就開始將我們最大的數據表格之一遷移到一套獨立的集羣上，這個步驟作為整個遷移過程的早期測試，以保證我們的核心集羣有更多的緩存池空間，並且為故障切換和存儲功能提供更強的靈活性。這步初始遷移方案也引入了一個有趣的挑戰：我們必須維持多條客户連接，並且要將這些連接指向到正確的集羣上。</p><p>除了硬件性能的提升，還需要補充一點，我們同時也對處理進程和拓撲結構進行了改進：我們添加了延時拷貝技術，更快、更高頻地備份數據，以及更多的讀拷貝空間。這些功能已經準備上線。</p><h3 id="列出任務清單-三思後行" tabindex="-1">列出任務清單，三思後行 <a class="header-anchor" href="#列出任務清單-三思後行" aria-label="Permalink to “列出任務清單，三思後行”">​</a></h3>',9)),e("p",null,[t[4]||(t[4]=a("每天有上百萬用户的使用 GitHub.com，我們不可能有機會等沒有人用了才進行實際數據切換。我們有一個詳細的",-1)),n(i,{href:"https://help.github.com/articles/writing-on-github#task-lists"},{default:s(()=>[...t[3]||(t[3]=[a("任務清單",-1)])]),_:1}),t[5]||(t[5]=a("來執行遷移：",-1))]),t[25]||(t[25]=e("p",null,[e("img",{src:"https://cloud.githubusercontent.com/assets/1155781/4116929/13fc6f50-328b-11e4-837b-922aad3055a8.png",alt:""})],-1)),e("p",null,[t[7]||(t[7]=a("我們還規劃了一個維護期，並且",-1)),n(i,{href:"https://github.com/blog/1603-site-maintenance-august-31st-2013"},{default:s(()=>[...t[6]||(t[6]=[a("在我們的Blog中通知了大家",-1)])]),_:1}),t[8]||(t[8]=a("，讓用户注意到這件事情。",-1))]),t[26]||(t[26]=r('<h3 id="遷移時間到" tabindex="-1">遷移時間到 <a class="header-anchor" href="#遷移時間到" aria-label="Permalink to “遷移時間到”">​</a></h3><p>太平洋時間星期六上午5點，我們的遷移團隊上線集合對話，同時數據遷移正式開始：</p><p><img src="https://cloud.githubusercontent.com/assets/1155781/4060850/39f52cd4-2df3-11e4-9aca-1f54a4870d24.png" alt=""></p><p>我們將 GitHub 網站設置為維護模式，並在 Twitter 上發表聲明，然後開始按上述任務清單的步驟開始工作：</p><p><img src="https://cloud.githubusercontent.com/assets/1155781/4060864/54ff6bac-2df3-11e4-95da-b059c0ec668f.png" alt=""></p><p><strong>13 分鐘</strong>後，我們確保新的集羣能正常工作：</p><p><img src="https://cloud.githubusercontent.com/assets/1155781/4060870/6a4c0060-2df3-11e4-8dab-654562fe628d.png" alt=""></p><p>然後我們讓 GitHub.com 脱離維護模式，並且讓全世界的用户都知道我們的最新狀態：</p><p><img src="https://cloud.githubusercontent.com/assets/1155781/4060878/79b9884c-2df3-11e4-98ed-d11818c8915a.png" alt=""></p><p>大量前期的測試工作與準備工作，讓我們將維護期縮到最短。</p><h3 id="檢驗最終的成果" tabindex="-1">檢驗最終的成果 <a class="header-anchor" href="#檢驗最終的成果" aria-label="Permalink to “檢驗最終的成果”">​</a></h3><p>在接下來的幾周時間裏，我們密切監視着 GitHub.com 的性能和響應時間。我們發現遷移後網站的平均加載時間減少一半，並且在99%的時間裏，能減少<em>三分之二</em>：</p><p><img src="https://cloud.githubusercontent.com/assets/1155781/4060886/9106e54e-2df3-11e4-8fda-a4c64c229ba1.png" alt=""></p><h3 id="我們學到了什麼" tabindex="-1">我們學到了什麼 <a class="header-anchor" href="#我們學到了什麼" aria-label="Permalink to “我們學到了什麼”">​</a></h3><h4 id="功能劃分" tabindex="-1">功能劃分 <a class="header-anchor" href="#功能劃分" aria-label="Permalink to “功能劃分”">​</a></h4><p>在遷移過程中，我們採用了一個比較好的方法是：將大的數據表（主要記錄了一些歷史數據）先遷移過去，空出舊集羣的磁盤空間和緩存池空間。這一步給我們留下了更多的資源用於“熱”數據，將一些連接請求分離到多套集羣裏面。這步為我們之後的勝利奠定了基礎，我們以後還會使用這種模式來進行遷移工作。</p><h4 id="測試測試測試" tabindex="-1">測試測試測試 <a class="header-anchor" href="#測試測試測試" aria-label="Permalink to “測試測試測試”">​</a></h4><p>為你的應用做驗收測試和迴歸測試，越多越好，多多益善，不要嫌多。從老集羣複製數據到新集羣的過程中，如果進行驗收測試和響應狀態測試，得到的數據是不準的，如果數據不理想，這是正常的，不要驚訝，不要試圖拿這些數據去分析原因。</p><h4 id="合作的力量" tabindex="-1">合作的力量 <a class="header-anchor" href="#合作的力量" aria-label="Permalink to “合作的力量”">​</a></h4><p>對基礎架構進行大的改變，通常需要涉及到很多人，我們要像一個團隊一樣為共同的目標而合作。我們的團隊成員來自全球各地。</p><p>團隊成員地圖：</p>',21)),e("p",null,[n(i,{href:"https://render.githubusercontent.com/view/geojson?url=https://gist.githubusercontent.com/anonymous/5fa29a7ccbd0101630da/raw/map.geojson"},{default:s(()=>[...t[9]||(t[9]=[a("https://render.githubusercontent.com/view/geojson?url=https://gist.githubusercontent.com/anonymous/5fa29a7ccbd0101630da/raw/map.geojson",-1)])]),_:1})]),t[27]||(t[27]=e("p",null,"本次合作新創了一種工作流程：我們提交更改（pull request），獲取實時反饋，查看修改了錯誤的 commit —— 全程沒有電話交流或面對面的會議。當所有東西都可以通過 URL 提供信息，不同區域的人羣之間的交流和反饋會變得非常簡單。",-1)),t[28]||(t[28]=e("h3",{id:"一年後",tabindex:"-1"},[a("一年後…… "),e("a",{class:"header-anchor",href:"#一年後","aria-label":"Permalink to “一年後……”"},"​")],-1)),t[29]||(t[29]=e("p",null,"整整一年時間過去了，我們很高興地宣佈這次數據遷移是很成功的 —— MySQL 性能和可靠性一直處於我們期望的狀態。另外，新的集羣還能讓我們進一步去升級，提供更好的可靠性和響應時間。我將繼續記錄這些優化過程。",-1)),t[30]||(t[30]=e("hr",null,null,-1)),e("p",null,[t[11]||(t[11]=a("via: ",-1)),n(i,{href:"https://github.com/blog/1880-making-mysql-better-at-github"},{default:s(()=>[...t[10]||(t[10]=[a("https://github.com/blog/1880-making-mysql-better-at-github",-1)])]),_:1})]),e("p",null,[t[15]||(t[15]=a("作者：",-1)),n(i,{href:"https://github.com/samlambert"},{default:s(()=>[...t[12]||(t[12]=[a("samlambert",-1)])]),_:1}),t[16]||(t[16]=a(" 譯者：",-1)),n(i,{href:"https://github.com/bazz2"},{default:s(()=>[...t[13]||(t[13]=[a("bazz2",-1)])]),_:1}),t[17]||(t[17]=a(" 校對：",-1)),n(i,{href:"https://github.com/wxy"},{default:s(()=>[...t[14]||(t[14]=[a("wxy",-1)])]),_:1})]),e("p",null,[t[20]||(t[20]=a("本文由 ",-1)),n(i,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...t[18]||(t[18]=[a("LCTT",-1)])]),_:1}),t[21]||(t[21]=a(" 原創翻譯，",-1)),n(i,{href:"http://linux.cn/"},{default:s(()=>[...t[19]||(t[19]=[a("Linux中國",-1)])]),_:1}),t[22]||(t[22]=a(" 榮譽推出",-1))])])}const M=l(d,[["render",b]]);export{y as __pageData,M as default};
